LoadSafes.syntax_text:
public void LoadSafes()
        {
            try
            {
                var adapter = new SqlDataAdapter(
                    "SELECT id, name FROM Safes WHERE status=1 AND IS_Deleted=0 ORDER BY id",
                    _conn);
                var table = new DataTable();
                adapter.Fill(table);

                cmbSafeFrom.DisplayMemberPath = "name";
                cmbSafeFrom.SelectedValuePath = "id";
                cmbSafeFrom.ItemsSource = table.DefaultView;
                cmbSafeFrom.SelectedIndex = -1;

                var table2 = table.Copy();
                cmbSafeTo.DisplayMemberPath = "name";
                cmbSafeTo.SelectedValuePath = "id";
                cmbSafeTo.ItemsSource = table2.DefaultView;
                cmbSafeTo.SelectedIndex = -1;
            }
            catch (Exception ex)
            {
                ShowError("خطأ في تحميل المستودعات", ex);
            }
        }

ShowError.syntax_text:
private void ShowError(string title, Exception ex)
            => DXMessageBox.Show($"{title}\n{ex.Message}", "خطأ",
                MessageBoxButton.OK, MessageBoxImage.Error);

Navigate.syntax_text:
public void Navigate(string sqlQuery)
        {
            try
            {
                EnsureOpen(_conn);
                using (var cmd = new SqlCommand(sqlQuery, _conn))
                using (var dr = cmd.ExecuteReader())
                    ReadData(dr);
            }
            catch (Exception ex)
            {
                DXMessageBox.Show("خطأ في التنقل: " + ex.Message);
            }
            finally
            {
                CloseConn(_conn);
            }
        }

public void Navigate(string sqlStr)
        {
            dgvSrch.UnselectAll();
            var cmd = new SqlCommand(sqlStr, conn);
            if (conn.State != ConnectionState.Open) conn.Open();
            ReadData(cmd.ExecuteReader());
            if (conn.State != ConnectionState.Closed) conn.Close();
        }

public void Navigate(string sqlQuery)
        {
            try
            {
                EnsureOpen(conn);
                var reader = new SqlCommand(sqlQuery, conn).ExecuteReader();
                ReadData(reader);
            }
            catch (Exception ex)
            {
                DXMessageBox.Show("خطأ في التنقل: " + ex.Message,
                                "خطأ", MessageBoxButton.OK, MessageBoxImage.Error);
            }
            finally { EnsureClose(conn); }
        }

